// ──────────────────────────────────────────────────────────────────────────
// 컴포넌트 라이브러리
// ──────────────────────────────────────────────────────────────────────────

func getAllComponents() -> [ComponentStyle] {
  let components: [ComponentStyle] = []

  components.push(createButtonComponent())
  components.push(createCardComponent())
  components.push(createInputComponent())
  components.push(createBadgeComponent())

  return components
}

func generateAllComponentStyles() -> string {
  let css = "/* FreeLang CSS Component Library */\n\n"

  for component in getAllComponents() {
    css = css + generateComponentCSS(component) + "\n"
  }

  return css
}

